function segDist(ax,ay,bx,by,px,py){const dx=bx-ax,dy=by-ay,l=dx*dx+dy*dy;let t=l?((px-ax)*dx+(py-ay)*dy)/l:0;t=clamp(t,0,1);return Math.hypot(ax+dx*t-px,ay+dy*t-py);}
function segPoint(ax,ay,bx,by,px,py){const dx=bx-ax,dy=by-ay,l=dx*dx+dy*dy;let t=l?((px-ax)*dx+(py-ay)*dy)/l:0;t=clamp(t,0,1);return{x:ax+dx*t,y:ay+dy*t};}
function segInter(ax,ay,bx,by,cx,cy,dx,dy){const r1=bx-ax,r2=by-ay,s1=dx-cx,s2=dy-cy,den=r1*s2-r2*s1;if(Math.abs(den)<1e-9)return false;const t=((cx-ax)*s2-(cy-ay)*s1)/den,u=((cx-ax)*r2-(cy-ay)*r1)/den;return t>=0&&t<=1&&u>=0&&u<=1;}
const fmt=n=>ru68(Math.round(n));/* PERF·OPT O-6 */
const pad2=n=>String(n).padStart(2,'0');
const LOMSVG='<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 1.4 13.7 4.7v6.6L8 14.6 2.3 11.3V4.7Z" fill="#141c28" stroke="#c9d2de" stroke-width="1.4" stroke-linejoin="round"/><path d="M8 1.4 13.7 4.7 8 8Z" fill="#ffb84d" opacity=".9"/><circle cx="8" cy="8" r="2.3" fill="#04060c" stroke="#c9d2de" stroke-width="1.2"/></svg>';
const fmtN=n=>typeof n==='number'?ru68(Math.round(n)):n;/* PERF·OPT O-6 */
function lomH(n,big){return `<span class="lom${big?' big':''}">${LOMSVG}<b>${fmtN(n)}</b></span>`;}
function store(k,v){/*DEVW*/if(v!==undefined&&window.DEVW&&DEVW.block(k))return null;try{if(v===undefined){const s=LS.getItem(k);return s?JSON.parse(s):null;}LS.setItem(k,JSON.stringify(v));G.saveFail=0;}catch(e){if(v!==undefined&&k==='void_world'&&!G.saveFail&&!(window.CLOUD&&CLOUD.state==='ready')){G.saveFail=1;try{toast('СОХРАНЕНИЕ НЕ ЗАПИСАНО','Браузер не даёт записать прогресс: хранилище переполнено или запрещено. Скопируйте код сохранения в меню, иначе прогресс пропадёт.');}catch(_){}}return null;}}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.random()*(i+1)|0;[a[i],a[j]]=[a[j],a[i]];}return a;}

// ---------- Настройки и рекорд ----------
const SET_DEF={amb:true,ambVol:.6,sfx:true,fx:true,manual:true,radio:true,zoom:1,btnSize:1,btnAlpha:.7,hand:'r',stick:'float',dashSwipe:true,haptics:true,softInv:false,oneHand:false,quality:'auto',fps:60,textScale:1,fsMode:(window.matchMedia&&matchMedia('(pointer:coarse)').matches)?'auto':'off',orient:'auto',fsHintShown:false,shake:1,noErase:false,lessFx:false};
const SET_OPT={fsMode:['off','auto','always'],orient:['auto','land','port'],zoom:[.85,1,1.15],btnSize:[.85,1,1.2],btnAlpha:[.45,.7,1],hand:['r','l'],stick:['float','fixed'],quality:['auto',0,1,2],fps:[60,30],textScale:[1,1.15,1.3],shake:[0,.5,1]};
const SET=Object.assign({},SET_DEF,(()=>{const v=store('void_settings');return v&&typeof v==='object'&&!Array.isArray(v)?v:{};})());
for(const k in SET_DEF){const d=SET_DEF[k];if(SET_OPT[k]){if(!SET_OPT[k].includes(SET[k]))SET[k]=d;}else if(typeof SET[k]!==typeof d||(typeof d==='number'&&!Number.isFinite(SET[k])))SET[k]=d;}
if(SET.ambVol<0||SET.ambVol>1)SET.ambVol=SET_DEF.ambVol;
// 0.6.2: миграция autoFs (0.6.1) → fsMode
{const raw=store('void_settings');if(raw&&typeof raw==='object'&&typeof raw.autoFs==='boolean'&&raw.fsMode===undefined)SET.fsMode=raw.autoFs?'auto':'off';delete SET.autoFs;}
const REC=Object.assign({best:0,maxMission:0,seen:['scout']},store('void_record')||{});
if(!Array.isArray(REC.seen))REC.seen=['scout'];
function saveSet(){store('void_settings',SET);}
function saveRec(){if(devAny())return;store('void_record',REC);}
function recReload(){const s=store('void_record')||{};for(const k in REC)delete REC[k];Object.assign(REC,{best:0,maxMission:0,seen:['scout']},s);}
function saveKey(){/*DEVW*/return window.DEVW&&DEVW.on()?'void_devworld':'void_world';}

// ---------- Аудио (WebAudio, синтез без файлов) ----------
const AU={ctx:null};
function audioInit(){
  if(AU.ctx){if(AU.ctx.state!=='running'&&AU.ctx.state!=='closed'){try{AU.ctx.resume();}catch(e){}}return;}
  try{
    const A=window.AudioContext||window.webkitAudioContext;const c=new A();AU.ctx=c;
    AU.amb=c.createGain();AU.amb.gain.value=0;AU.amb.connect(c.destination);
    AU.sfx=c.createGain();AU.sfx.gain.value=.32;const slp=c.createBiquadFilter();slp.type='lowpass';slp.frequency.value=4200;AU.sfx.connect(slp);slp.connect(c.destination);
    musInit();
    AU.pingT=6;applyAudio();
  }catch(e){AU.ctx=null;}
}
function applyAudio(){if(!AU.ctx)return;const t=AU.ctx.currentTime;AU.amb.gain.setTargetAtTime(SET.amb?SET.ambVol*.55:0,t,.6);}
const sfxLast={};
const PENTA=[523.25,587.33,659.25,783.99,880];
function sfx(n){
  if(!AU.ctx||!SET.sfx)return;const c=AU.ctx,t=c.currentTime;
  const lim={shot:.07,hit:.04,pick:.03,block:.05,boom:.05,bhit:.15,kill:.05,killBig:.08};if(lim[n]){if(sfxLast[n]&&t-sfxLast[n]<lim[n])return;sfxLast[n]=t;}
  const tone=(f0,f1,dur,type,vol,delay=0)=>{const o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(f0,t+delay);o.frequency.exponentialRampToValueAtTime(Math.max(20,f1),t+delay+dur);g.gain.setValueAtTime(vol,t+delay);g.gain.exponentialRampToValueAtTime(.0001,t+delay+dur);o.connect(g);g.connect(AU.sfx);o.start(t+delay);o.stop(t+delay+dur+.02);};
  const noise=(dur,vol,f)=>{const len=c.sampleRate*dur|0,b=c.createBuffer(1,len,c.sampleRate),d=b.getChannelData(0);for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);const s=c.createBufferSource();s.buffer=b;const fl=c.createBiquadFilter();fl.type='lowpass';fl.frequency.value=f;const g=c.createGain();g.gain.value=vol;s.connect(fl);fl.connect(g);g.connect(AU.sfx);s.start(t);};
  switch(n){
    case 'shot':{const f=rnd(760,860);tone(f,f*.6,.07,'triangle',.034);tone(f*2.01,f*1.3,.045,'sine',.01);break;}
    case 'hit':tone(420,300,.04,'sine',.03);break;
    case 'kill':{const n=PENTA[Math.random()*5|0];tone(n,n,.16,'triangle',.06);tone(n*1.5,n*1.5,.2,'sine',.035,.04);noise(.12,.12,700);break;}
    case 'killBig':{const n=PENTA[Math.random()*5|0]/2;tone(n,n,.32,'triangle',.08);tone(n*1.5,n*1.5,.36,'sine',.05,.05);tone(n*2,n*2,.3,'sine',.03,.1);noise(.3,.22,500);break;}
    case 'boom':noise(.35,.35,700);tone(110,45,.35,'sine',.22);break;
    case 'bigboom':noise(1.4,.8,600);tone(80,25,1.3,'sine',.5);break;
    case 'pick':tone(900,1500,.08,'sine',.09);break;
    case 'cell':tone(500,1000,.12,'triangle',.12);tone(1000,1600,.12,'sine',.08,.08);break;
    case 'dash':noise(.18,.25,2400);tone(200,600,.15,'sawtooth',.05);break;
    case 'hurt':tone(220,60,.25,'sawtooth',.16);noise(.2,.3,1200);break;
    case 'shield':tone(1200,400,.2,'triangle',.12);break;
    case 'pulse':tone(90,30,.7,'sine',.5);noise(.6,.4,1600);break;
    case 'level':[523,659,784,1046].forEach((f,i)=>tone(f,f,.18,'triangle',.09,i*.07));break;
    case 'warn':tone(660,660,.12,'square',.05);tone(660,660,.12,'square',.05,.18);break;
    case 'block':tone(1800,900,.05,'square',.03);break;
    case 'bhit':tone(180,90,.2,'square',.07);break;
    case 'flash':[392,523,659].forEach((f,i)=>tone(f,f*2,.5,'sine',.08,i*.05));break;
    case 'charged':tone(1400,300,.35,'sawtooth',.06);tone(700,180,.4,'triangle',.12);noise(.25,.25,3000);break;
  }
}

// ---------- Холст и масштаб ----------
const cv=$('#cv');let ctx=cv.getContext('2d');
let DPR=1,SC=1,W=900,H=600,CW=900,CH=600;
let BW=900,BH=600,CX=0,CY=0,VW=900,VH=600,BMIN=0;
let nebula=null,stars=[],darkC=null,dctx=null;
// 0.6.0: видимый мир и разрешение рендера разделены. ПК — 760 единиц на короткую сторону (как раньше), телефон — 560, планшет — 680.
function viewS(){return G.ff==='desk'?760:G.ff==='tablet'?680:560;}
function zoomK(){return (isMob()?(SET.zoom||1):1)*(G.camZ||1);}
function applyWH(){if(G.arena&&!G.world){W=G.arena.w;H=G.arena.h;}else{W=VW;H=VH;}}
function setScale(){SC=Math.max(.42,Math.min(CW,CH)/(viewS()*zoomK()));VW=CW/SC;VH=CH/SC;applyWH();BMIN=isMob()?2.2/SC:0;}
function dprCap(){const q=G.q,cap=q>=2?2:q===1?1.5:1;return Math.min(cap,Math.sqrt(2.2e6/Math.max(1,CW*CH)));}
let rsW=0,rsH=0;
function resize(){
  ffUpdate();CW=window.innerWidth;CH=window.innerHeight;DPR=Math.min(isMob()?dprCap():2,window.devicePixelRatio||1);
  cv.width=Math.round(CW*DPR);cv.height=Math.round(CH*DPR);
  setScale();
  // туманность и звёзды — только при заметной смене размера (адресная строка дёргает resize десятки раз), на ПК — как раньше
  if(!isMob()||Math.abs(CW-rsW)>64||Math.abs(CH-rsH)>64||!nebula||(CW>CH)!==(rsW>rsH)){rsW=CW;rsH=CH;buildNebula();buildStars();}
  if(G.player&&!G.world&&!G.arena){G.player.x=clamp(G.player.x,20,W-20);G.player.y=clamp(G.player.y,20,H-20);}
  if(G.bc&&!G.arena)layoutBeacon();
  if(G.world&&G.player)camSnap();
  if(G.arena&&!G.world&&G.player){G.camSnap=1;missionCam(0);}
  if(typeof layoutTouch==='function')layoutTouch();
}
// арена миссии на телефоне и планшете: 1280×760, длинной стороной вдоль длинной стороны экрана; на ПК арена = экран
function lockArena(){if(!isMob()){G.arena=null;applyWH();return;}G.arena=CW>=CH?{w:1280,h:760}:{w:760,h:1280};applyWH();}
function unlockArena(){G.arena=null;applyWH();}
function missionCam(dt){
  if(!G.arena){CX=0;CY=0;return;}
  const p=G.player;if(!p){CX=(W-VW)/2;CY=(H-VH)/2;return;}
  const off=isPortrait()?.12:.06;let tx=p.x+(p.vx||0)*.35-VW/2,ty=p.y+(p.vy||0)*.35-VH/2+VH*off;
  if(G.bc){tx=tx*.7+(G.bc.x-VW/2)*.3;ty=ty*.7+(G.bc.y-VH/2)*.3;}
  const fx=W>VW?clamp(tx,0,W-VW):(W-VW)/2,fy=H>VH?clamp(ty,0,H-VH):(H-VH)/2;
  const k=G.camSnap||!(dt>0)?1:Math.min(1,dt*6);G.camSnap=0;CX+=(fx-CX)*k;CY+=(fy-CY)*k;}
function buildNebula(){
  const c=document.createElement('canvas');c.width=Math.max(2,CW*DPR/2|0);c.height=Math.max(2,CH*DPR/2|0);const g=c.getContext('2d');
  g.fillStyle='#04060c';g.fillRect(0,0,c.width,c.height);
  const blobs=[['rgba(70,40,140,',.22],['rgba(20,80,130,',.2],['rgba(120,30,70,',.1],['rgba(30,110,140,',.12]];
  for(let i=0;i<7;i++){const [col,a]=blobs[i%blobs.length];const x=Math.random()*c.width,y=Math.random()*c.height,r=rnd(.3,.75)*Math.max(c.width,c.height);
    const gr=g.createRadialGradient(x,y,0,x,y,r);gr.addColorStop(0,col+a+')');gr.addColorStop(1,col+'0)');g.fillStyle=gr;g.fillRect(0,0,c.width,c.height);}
  nebula=c;
}
function buildStars(){
  stars=[];const n=Math.round(W*H/2600);
  for(let i=0;i<n;i++){const l=Math.random();stars.push({x:Math.random()*W*1.2-W*.1,y:Math.random()*H*1.2-H*.1,k:l<.6?.02:l<.9?.05:.1,s:l<.6?.8:l<.9?1.3:2,tw:Math.random()*TAU});}
}
const glowCache={};
function glowSprite(col){
  if(glowCache[col])return glowCache[col];const c=document.createElement('canvas');c.width=c.height=64;const g=c.getContext('2d');
  const gr=g.createRadialGradient(32,32,0,32,32,32);gr.addColorStop(0,col);gr.addColorStop(.35,col+'66');gr.addColorStop(1,col+'00');g.fillStyle=gr;g.fillRect(0,0,64,64);
  return glowCache[col]=c;
}
function glow(x,y,r,col,a=1){if((!SET.fx||G.lowFx)&&r>30||GLOWMAX&&r>GLOWMAX)return;const ga=ctx.globalAlpha;ctx.globalAlpha=ga*a;ctx.drawImage(glowSprite(col),x-r,y-r,r*2,r*2);ctx.globalAlpha=ga;}

