// сила пилота: по максимальному открытому сектору, а не по месту, где корабль сейчас (0.7.4)
const PLAYER_TIER_CAP=3;// ВРЕМЕННО (альфа 0.7.4): пока готовятся сектора III–IV, пилот считается на уровне сектора IV
function playerTier(){if(G.mode!=='world'&&G.mode!=='dev')return 0;const S=G.save;if(ALPHA_OPEN||G.mode==='dev')return PLAYER_TIER_CAP;if(!S)return 0;
  let t=S.gate||S.cleared>=CORE?2:0;for(let i=3;i<=PLAYER_TIER_CAP;i++){const q=SECTORS_NEW[i-3];if(q&&S.medals&&S.medals[q.lv[1]]&&S.medals[q.lv[1]].clear)t=i;}return Math.min(t,PLAYER_TIER_CAP);}
function playerDmgK(){const SS=SEC_SCALE[playerTier()];return SS?SS.dmg:1;}
Object.assign(EDEF,{
  cocoon:{name:'Кокон',hp:40,spd:0,r:15,xp:3,contact:0,col:'#ff9fb8',pts:60,act:3,m:19,sec:4,
    desc:'Не стреляет и не двигается. Через 8 секунд вылупляется врагом из состава волны — на ступень сильнее обычного (прочнее и с аффиксом). Чем выше эрозия, тем быстрее зреет кладка; песня Певчего ускоряет её вдвое. Разбитый кокон отдаёт данные.',
    lore:'«Ждёт места в истории. Вы его освобождаете». Ковчег сохранил их мёртвых — для нерождённых места не осталось.'},
  unborn:{name:'Нерождённый',hp:10,spd:205,r:9,xp:1,contact:14,col:'#ffc2d4',pts:25,act:3,m:19,sec:4,
    desc:'Мелкий быстрый роевой. Первую секунду полупрозрачен и неуязвим — «ещё не случился»; потом бросается на корабль и гибнет при ударе. Не тратьте заряд в призрака — импульс снимает всю стаю.',
    lore:'История, которой не дали начаться.'},
  pestun:{name:'Пестун',hp:55,spd:95,r:16,xp:5,contact:10,col:'#ff6b8a',pts:90,act:3,m:20,sec:4,
    desc:'Несёт два кокона и рассаживает их по углам арены. Убитый роняет оставшиеся коконы — они вылупляются уже через 3 секунды. Ловите до посадки.',
    lore:'Уносит детей туда, где вы их не заметите.'},
  membrane:{name:'Мембрана',hp:70,spd:40,r:14,xp:4,contact:0,col:'#ff8fa8',pts:70,act:3,m:20,sec:4,
    desc:'Живая стена длиной 160 встаёт между вами и стаей. Обычные снаряды вязнут, вражеские проходят насквозь. Рвётся только зарядом, «Разрывом», импульсом или рывком сквозь неё.',
    lore:'Изнутри видно только свет.'},
  cord:{name:'Пуповина',hp:40,spd:110,r:12,xp:4,contact:10,col:'#ff7fa0',pts:80,act:3,m:21,sec:4,
    desc:'Пара, связанная живым тросом: каждый лечит другого, трос бьёт при пересечении. Убейте одного — второй слабеет вдвое. Рывок сквозь трос рвёт связь.',
    lore:'Последняя связь матери и ребёнка. Или архива и записи.'},
  singer:{name:'Певчий',hp:45,spd:70,r:14,xp:6,contact:8,col:'#ffd0e0',pts:110,act:3,m:21,sec:4,
    desc:'Не атакует. Поёт: союзники в радиусе 220 быстрее на 30%, коконы рядом зреют вдвое быстрее. Приоритет номер один в любой стае.',
    lore:'Колыбельная на языке, которого нет в каталоге.'},
  embryo:{name:'Зародыш стража',hp:30,spd:35,r:10,xp:3,contact:8,col:'#ffb8c8',pts:50,act:3,m:22,sec:4,
    desc:'Рождается слабым и за 20 секунд дорастает до Гвардии со щитом (у Кормилицы — за 10). Кольцо роста видно. Убить рано — дёшево, поздно — дорого.',
    lore:'Стражей тоже когда-то вынашивали. Здесь.'},
  lastkind:{name:'Последний из вида',hp:420,spd:55,r:26,xp:0,contact:0,col:'#ffe0ea',pts:400,act:3,m:19,sec:4,
    desc:'Редкий. Не атакует и за 15 секунд уходит за край арены. Убить — много опыта и лома. Отпустить — его запомнят.',
    lore:'Несёт последнюю кладку своего народа.'},
  vent:{name:'Устье колыбели',hp:60,spd:0,r:20,xp:0,contact:0,col:'#ff6b8a',pts:60,passive:true},
  womb:{name:'Утроба',hp:200,spd:0,r:24,xp:0,contact:10,col:'#ff6b8a',pts:120,passive:true,sbp:true},
  nurse:{name:'Кормилица',hp:11000,spd:0,r:58,xp:0,contact:24,col:'#ff6b8a',pts:20000,act:3,m:22,sec:4,sb:'nurse',sbp:true,
    desc:'Последняя живая колыбель на четырёх пуповинах. Фаза 1 «Колыбельная»: пока цела хоть одна пуповина, тело неуязвимо; пуповину рвут два заряда, три попадания «Разрыва» или два импульса у утробы; обычный огонь рвёт её очень медленно (сто попаданий). Кольца песни расходятся с «окном» — пролетайте в него. Порванная утроба роняет молоко: +10% прочности. Фаза 2 «Схватки»: арена сжимается рывками, тело уязвимо только на вдохе (светлая мембрана), рождаются Зародыши стража. Фаза 3 «Последний ребёнок»: кольца без окна (рывок) и споры, сбивающие снаряды. В финале выбор: прервать или выносить.',
    lore:'В самом ценном коконе зреет не чужой ребёнок. Его контур — корабль VØID. Номер цикла — следующий после вашего.'},
  autopilot:{name:'Автопилот',hp:35,spd:170,r:12,xp:4,contact:10,col:'#c9d2de',pts:70,act:3,m:23,sec:5,
    desc:'Мёртвый истребитель флота летает «восьмёркой» и стреляет по ближайшему кораблю — по вам или по другим врагам. Затяните его в толпу.',
    lore:'Исполняет последний приказ. Приказ был: стрелять.'},
  battery:{name:'Батарея',hp:90,spd:0,r:15,xp:5,contact:8,col:'#9fb0c4',pts:90,act:3,m:23,sec:5,
    desc:'Турель на дрейфующем корпусе: держит сектор 90° и бьёт залпом из пяти снарядов. Поворачивается вместе с корпусом — заходите со спины.',
    lore:'Держит палубу, которой нет.'},
  boarder:{name:'Абордажник',hp:30,spd:185,r:11,xp:4,contact:0,col:'#ffb84d',pts:70,act:3,m:24,sec:5,
    desc:'Присасывается к кораблю: −30% скорости и износ брони, пока висит. Сбросить — рывком или импульсом; сброшенный оглушён и теряет половину прочности.',
    lore:'Идёт на абордаж корабля Стражей. Ваш корабль ему похож.'},
  fireship:{name:'Брандер',hp:50,spd:80,r:16,xp:5,contact:0,col:'#ff7a3d',pts:80,act:3,m:24,sec:5,
    desc:'Медленный огненный корабль разгоняется к вам и взрывается на радиус 180. Подорванный раньше — взрывается там, где стоит, и жжёт соседей. Встречайте его посреди стаи.',
    lore:'Его настроили на любой корабль без опознавания.'},
  signaller:{name:'Связист',hp:40,spd:70,r:13,xp:5,contact:0,col:'#9fd8ff',pts:90,act:3,m:25,sec:5,
    desc:'Пока жив, враги на экране стреляют согласованным залпом по его отсчёту 3–2–1. Снимайте первым или пережидайте залп рывком.',
    lore:'Передаёт команду «огонь». Отвечают только мёртвые.'},
  turncoat:{name:'Крейсер-перебежчик',hp:180,spd:45,r:26,xp:12,contact:16,col:'#d6dee8',pts:260,act:3,m:25,sec:5,
    desc:'Элита. Борта бронированы (урон ×0,25), уязвим с носа и кормы. Стреляет по правилу Стражей — по двигателям: урон меньше, но каждое попадание глушит ваши двигатели.',
    lore:'Перешёл на сторону Стражей. Знал что-то, чего не знал флот.'},
  cadet:{name:'Курсант',hp:30,spd:120,r:11,xp:3,contact:8,col:'#8fe9ff',pts:50,act:3,m:23,sec:5,
    desc:'Слабый, стреляет неточно. На трети прочности уходит из боя — не добивайте, и он вас запомнит.',
    lore:'«Мама обещала встретить в порту».'},
  sporer:{name:'Споровик',hp:40,spd:75,r:14,xp:5,contact:8,col:'#ffd0a0',pts:80,act:3,m:20,sec:4,
    desc:'Раскидывает облака спор радиусом 90 на 8 секунд: внутри ваши снаряды теряют скорость и сворачивают. Стреляйте из-за облака — импульс разгоняет споры.',
    lore:'Сеет там, где вы освободили место.'},
  absorber:{name:'Поглотитель',hp:60,spd:60,r:16,xp:8,contact:12,col:'#ff9fe0',pts:150,act:3,m:21,sec:4,
    desc:'Вбирает ваши обычные снаряды и «Разрыв» и растёт; на 25 снарядах лопается веером из 25 выстрелов. Ранит его только заряд, импульс или таран — обычный огонь его только кормит.',
    lore:'Делает то же, что и вы. Только честнее.'},
  linkor:{name:'Скелет линкора',hp:600,spd:24,r:42,xp:30,contact:20,col:'#d6dee8',pts:1500,act:3,m:26,sec:5,
    desc:'Мини-босс. Огромный медленный корпус с четырьмя батареями и двумя двигателями; каждые 8 секунд — бортовой залп в вашу сторону. Выбейте оба двигателя — он встанет, залпы реже. Держитесь у носа или кормы.',
    lore:'Последний из трёх линкоров флота.'},
  echoship:{name:'Эхо флота',hp:40,spd:60,r:14,xp:0,contact:0,col:'#b8c4d6',pts:0,passive:true},
  echoguard:{name:'Эхо Стража',hp:40,spd:60,r:14,xp:0,contact:0,col:'#ffb84d',pts:0,passive:true},
  fpart:{name:'Секция флагмана',hp:900,spd:0,r:22,xp:0,contact:14,col:'#b8c4d6',pts:150,passive:true,sbp:true},
  flagship:{name:'Последний довод',hp:15000,spd:0,r:30,xp:0,contact:20,col:'#d6dee8',pts:22000,act:3,m:27,sec:5,sb:'flag',sbp:true,
    desc:'Флагман флота и его адмирал, сросшийся с кораблём. Шесть секций: нос, две батареи, рубка, два двигателя. Фаза 1: бортовые залпы веером, рубка бронирована. Фаза 2: если выбит хоть один двигатель, флагман теряет управление и вращается — залпы метут всю арену; ангар выпускает абордажников и брандеры. Фаза 3: рубка открыта (урон ×1,5), залп «Последний довод» бьёт туда, где вы были секунду назад. В финале: по рубке или по двигателям.',
    lore:'Стражи 127 лет назад стреляли по двигателям, не по рубке. Адмирал Карр так и не понял почему — и все эти годы продолжает бой.'}
});
CODEX_ORDER.push('cocoon','unborn','pestun','membrane','sporer','absorber','cord','singer','embryo','lastkind','nurse','autopilot','battery','boarder','fireship','signaller','turncoat','cadet','linkor','flagship');
['vent','womb','fpart','battery','nurse','flagship'].forEach(k=>STATIC.add(k));
['vent','womb','fpart','battery','nurse','flagship','cocoon','linkor','turncoat','membrane'].forEach(k=>HEAVY.add(k));
['membrane','vent','echoship','echoguard','lastkind'].forEach(k=>NOAUTO.add(k));
Object.assign(SEC_WAVES,{
  19:{nw:['cocoon','unborn'],old:['gunner','phantom','shocker','lancer','frost'],share:.25,debut:'cocoon',brood:.18},
  20:{nw:['pestun','membrane','unborn','sporer'],old:['shade','mirror','hunter','gunner','phantom'],share:.3,debut:'pestun',brood:.18},
  21:{nw:['cord','singer','unborn','absorber'],old:['pestun','membrane','sporer','shocker','phantom','hunter','guard'],share:.35,debut:'singer',brood:.2},
  22:{nw:['unborn','singer','cord'],old:['pestun','membrane','sporer','absorber','phantom','hunter'],share:.45,brood:.2},
  23:{nw:['autopilot','cadet'],old:['unborn','pestun','singer','phantom','gunner','hunter'],share:.3,debut:'autopilot'},
  24:{nw:['boarder','fireship','autopilot'],old:['cadet','shade','lancer','gunner','phantom'],share:.3,debut:'boarder'},
  25:{nw:['signaller','fireship','turncoat'],old:['autopilot','boarder','cadet','hunter','mirror'],share:.35,debut:'signaller'},
  26:{nw:['turncoat','boarder','signaller'],old:['autopilot','cadet','fireship','phantom','shocker'],share:.4},
  27:{nw:['autopilot','boarder','fireship'],old:['cadet','signaller','turncoat','hunter','phantom'],share:.45}});
Object.assign(SEC_LIM,{sporer:2,absorber:1,membrane:2,singer:2,pestun:2,cord:2,lastkind:0,turncoat:1,signaller:1,fireship:3,boarder:3,cocoon:4});
['unborn','boarder','autopilot','cadet','cord'].forEach(k=>SEC_FAST.add(k));
['membrane','turncoat','signaller','singer','cocoon','pestun','absorber'].forEach(k=>SEC_SLOW.add(k));
['unborn','boarder','cadet'].forEach(k=>SEC_CHASER.add(k));
