const C90={ark:'#ffd36b',red:'#d8364a',blood:'#ff4f6e',warm:'#ffe9b0',bg:'#1a0a0e',sh:'#7affc9',sh2:'#cfe8e0',shbg:'#0b1114',pil:'#dfe8ff',white:'#f4fff9'};
Object.assign(EDEF,{
  clot90:{name:'Тромб',hp:70,spd:55,r:18,xp:5,contact:14,col:'#d8364a',pts:120,act:4,m:39,sec:8,
    desc:'Сгусток крови Ковчега. Медленно ползёт к вам и, если его не трогать, растекается лужей радиусом 46 на 10 секунд: в луже корабль вязнет, а враги прячутся. Одновременно — не больше четырёх луж. Импульс и заряд растворяют и лужи, и сам Тромб.',
    lore:'Ковчег лечит пробоины так, как умеет: закрывает их собой.'},
  valve90:{name:'Клапан',hp:120,spd:0,r:22,xp:8,contact:16,col:'#ffd36b',pts:180,act:4,m:39,sec:8,
    desc:'Створка кровотока. Бьётся тактами по 1,2 секунды: три такта открыт и уязвим, на четвёртом захлопывается и бьёт волной радиусом 110 (18 урона). Пока жив — перекрывает свой поток на закрытом такте. Импульс рядом с Клапаном сбивает ему ритм и глушит поток на 8 секунд.',
    lore:'Он не знает, что кровь давно не нужна. Он просто пропускает её дальше.'},
  keeper90:{name:'Смотритель',hp:40,spd:110,r:13,xp:6,contact:0,col:'#ffe9b0',pts:140,act:4,m:40,sec:8,
    desc:'Санитар Ковчега. Патрулирует с конусом обзора 70° и длиной 240. Продержитесь в конусе 0,6 с — вас заметят: Тревога растёт, Смотритель держит дистанцию 320 и бьёт очередями. Если рядом капсула — за 3 с будит спящего силой. Попадание в спину (сзади больше 110°) — урон ×2, а убийство сзади — «ТИХО»: Тревога падает.',
    lore:'«Пассажиров не будить до прибытия». Прибытие так и не наступило.'},
  phago90:{name:'Фагоцит',hp:60,spd:85,r:16,xp:6,contact:10,col:'#ff8a5c',pts:150,act:4,m:40,sec:8,
    desc:'Клетка-уборщик. Кружит вокруг вас на 90 пикселях и глотает обычные снаряды — каждый ранит его вдвое слабее и раздувает. Наевшись (10 снарядов), лопается веером осколков. Заряд и «Разрыв» бьют по нему ×1,5, импульс сдувает его обратно.',
    lore:'Ест всё, что движется не по кровотоку. Вы движетесь не по кровотоку.'},
  neuron90:{name:'Нейрон',hp:45,spd:0,r:14,xp:4,contact:0,col:'#ffe47a',pts:100,act:4,m:41,sec:8,
    desc:'Узел нервной сети. Появляется группами по 3–4 и связывается лучами: враги в 220 от живой сети на 20% быстрее и атакуют на 25% чаще. Рывок сквозь луч рвёт его на 4 секунды. Самый слабый узел отмечен — с него сеть рассыпается быстрее. Автоприцел выбирает Нейроны охотнее.',
    lore:'Ковчег думает медленно. Но думает только о вас.'},
  embryo90:{name:'Эмбрион',hp:25,spd:0,r:12,xp:3,contact:0,col:'#ff9fb0',pts:60,act:4,m:41,sec:8,
    desc:'Капля в мембране. Через 15 секунд (на «Хардкоре» — 12) вылупляется копией ближайшего врага: «Перерождённый» прочнее в 1,4 раза и бьёт на 20% сильнее, но ничего не роняет. Рядом нет врагов — вылупится Тромб. Одновременно — не больше четырёх.',
    lore:'Ковчег запомнил всех, кого видел. И повторяет.'},
  pass90:{name:'Пассажир',hp:80,spd:120,r:14,xp:0,contact:0,col:'#dfe8ff',pts:0,passive:true,act:4,m:40,sec:8,
    desc:'Спящий из капсулы, которого Смотритель разбудил силой. Ещё не понимает, где он, но стреляет по врагам. Автоприцел его не трогает, ваши снаряды — трогают: ранили — 4 секунды отвечает вам. Через минуту улетает в глубину Ковчега. Убитый Пассажир — потерянный.',
    lore:'Он проснулся не там и не тогда. Как и вы.'},
  heart90:{name:'Сердце',hp:12500,spd:0,r:52,xp:0,contact:14,col:'#ffd36b',pts:28000,act:4,m:42,sec:8,sb:'heart',sbp:true,
    desc:'Сердце Ковчега в камере из четырёх сосудов. Бьётся тактами: на систоле сжимается (урон по нему ×0,15) и гонит кольцевую волну, на диастоле открыто. Последние 0,25 с перед ударом — «в такт»: урон ×1,6. Темп растёт по фазам: 50, 70, 90, 110 ударов. Фаза 2 — клапаны и аритмия, фаза 3 — двойные удары с проходами в волнах и тромбы, лечащие Сердце. Фаза 4 — Сердце встаёт: пролетите через четыре ключа ритма по часовой стрелке, по одному на удар. Четыре подряд — Сердце открыто, урон ×2.',
    lore:'ИСТОЧНИК НЕ ОПОЗНАН'},
  hvalve90:{name:'Клапан Сердца',hp:1000,spd:0,r:20,xp:0,contact:0,col:'#ffd36b',pts:120,passive:true,sbp:true},
  hkey90:{name:'Ключ ритма',hp:1000,spd:0,r:34,xp:0,contact:0,col:'#ffe9b0',pts:0,passive:true,sbp:true},
  thromb90:{name:'Сгусток',hp:1000,spd:0,r:18,xp:0,contact:0,col:'#d8364a',pts:60,passive:true,sbp:true},
  eraser100:{name:'Ластик',hp:55,spd:95,r:15,xp:5,contact:10,col:'#7affc9',pts:120,act:4,m:43,sec:9,
    desc:'Стирает пространство. Каждые 5 секунд кладёт зону радиусом 110 на 3 секунды (телеграф 0,6 с): в ней пусто — 6 урона в секунду, ход медленнее, ваши снаряды исчезают. Заряд проходит насквозь. Рывок сквозь самого Ластика оглушает его на 1,5 с. Зон Ластиков на арене — не больше трёх.',
    lore:'Здесь кто-то был. Ластик проверяет, что больше нет.'},
  hollow100:{name:'Пустотник',hp:45,spd:140,r:14,xp:6,contact:14,col:'#cfe8e0',pts:150,act:4,m:43,sec:9,
    desc:'Почти невидим. Кружит на 400 пикселях и раз в 4 секунды бросается на вас: за 0,45 с до броска слышен вдох — с той стороны, откуда он летит. После броска 1,2 с виден целиком. Импульс проявляет всех Пустотников рядом на 4 секунды. Автоприцел видит его только проявленным.',
    lore:'Контур того, кто забыл, как выглядит.'},
  witness100:{name:'Свидетель',hp:150,spd:85,r:14,xp:0,contact:0,col:'#ffffff',pts:0,passive:true,act:4,m:43,sec:9,
    desc:'Мирный корабль несёт обрывок памяти через стёртую арену к выходу. Враги охотнее бьют его, чем вас. Импульс рядом даёт ему щит на 3 секунды. Долетел — обрывок ваш и 30 лома. Погиб — обрывок потерян навсегда. Автоприцел его не трогает.',
    lore:'Он помнит то, что вы забыли. Ему тяжело это нести.'},
  typo100:{name:'Опечатка',hp:50,spd:110,r:14,xp:6,contact:10,col:'#b8ffe0',pts:150,act:4,m:44,sec:9,
    desc:'Враг, собранный из трёх случайных кусков других врагов: ход одного, оружие второго, привычка третьего. Каждая Опечатка — своя, имя на борту подсказывает, из чего она. Опасна тем, что непредсказуема: смотрите на подпись.',
    lore:'Ковчег пытался вспомнить врага. Вспомнил всех сразу.'},
  fixer100:{name:'Корректор',hp:50,spd:105,r:14,xp:6,contact:0,col:'#9fffd8',pts:150,act:4,m:44,sec:9,
    desc:'Летит к самому раненому врагу в радиусе 500, тянет к нему луч и за 1,5 с возвращает ему весь урон последних трёх секунд. Прервать ремонт: попадание на 15% прочности Корректора или рывок сквозь луч. Автоприцел выбирает его охотнее.',
    lore:'Исправляет ошибки. Ошибка — это то, что сделали вы.'},
  echo100:{name:'Эхо-призрак',hp:40,spd:0,r:13,xp:4,contact:0,col:'#e0fff4',pts:120,act:4,m:44,sec:9,
    desc:'Ваш собственный след. Летит маршрутом вашего прошлого успешного прохождения этой миссии (а если его нет — вашим путём двадцатисекундной давности) и раз в 1,2 с стреляет туда, где вы есть. Импульс стирает его.',
    lore:'Вы уже были здесь. Вы просто не помните.'},
  tide100:{name:'Прилив',hp:1000,spd:70,r:80,xp:0,contact:12,col:'#7affc9',pts:0,passive:true,act:4,m:45,sec:9,
    desc:'Неуязвимая полоса пустоты высотой 160 раз в 40 секунд проходит арену с одним проходом шириной 140. За 3 секунды — предупреждение у края. Первое касание — 12 урона, потом толкает; у края бросает в стирание. Стирает все снаряды. Рывок сквозь полосу — без урона. Свидетелей и сюжетные предметы не трогает.',
    lore:'Берег смывает то, что на нём написано. Вы на нём написаны.'},
  noname100:{name:'Безымянный',hp:90,spd:80,r:17,xp:10,contact:14,col:'#a0b4ae',pts:240,act:4,m:45,sec:9,
    desc:'У него нет полоски прочности. Каждые 3 секунды — веер из пяти снарядов по 9 урона. Пока вы целитесь в него, он «смотрит» в ответ и крепнет: броня до 70%. Отведите прицел — взгляд гаснет вдвое быстрее. Автоприцел, видя крепкий взгляд, переключается на других.',
    lore:'ИМЯ СТЁРТО'},
  shore100:{name:'Берег',hp:12500,spd:0,r:30,xp:0,contact:0,col:'#7affc9',pts:30000,act:4,m:46,sec:9,sb:'shore',sbp:true,
    desc:'Не тело, а край: сверху на арену опускается горизонт пустоты. Над ним — стёртое, касаться нельзя. Держит его цепь маяков памяти (5, 4 и 3 по фазам): маяк под щитом, пока вы дальше 260. Разбитый маяк роняет горизонт на 40. Дошёл до низа — отлив: горизонт откатывается, маяки 6 с без щита. Фаза 2 — пропадает интерфейс и приходят тени прошлых боссов. Фаза 3 — тишина и ваше собственное эхо.',
    lore:'ИСТОЧНИК НЕ ОПОЗНАН'},
  beacon100:{name:'Маяк памяти',hp:1000,spd:0,r:22,xp:0,contact:0,col:'#7affc9',pts:150,passive:true,sbp:true}
});
['valve90','neuron90','embryo90','heart90','hvalve90','hkey90','thromb90','shore100','beacon100','tide100'].forEach(k=>STATIC.add(k));
['valve90','heart90','hvalve90','shore100','beacon100','tide100'].forEach(k=>HEAVY.add(k));
['pass90','witness100','tide100','hkey90'].forEach(k=>NOAUTO.add(k));
CODEX_ORDER.push('clot90','valve90','keeper90','phago90','neuron90','embryo90','pass90','heart90','eraser100','hollow100','witness100','typo100','fixer100','echo100','tide100','noname100','shore100');
