// справочник: IX–X под своим заголовком; новые — рядом с родственными
['clot90','valve90','keeper90','phago90','neuron90','embryo90','pass90','heart90','eraser100','hollow100','witness100','typo100','fixer100','echo100','tide100','noname100','shore100'].forEach(k=>{if(EDEF[k])EDEF[k].act=5;});
