  for(let i=0;i<10;i++){const a=i/10*TAU;ctx.strokeStyle=over?(Math.sin(t*20+i)>0?'#ffffff':'#7c5cff'):'#7c5cff';ctx.beginPath();ctx.arc(0,0,R+16,a,a+TAU/10-.12);ctx.stroke();}
  ctx.restore();
