  ctx.save();ctx.rotate(-(j.rot||0)*2);ctx.setLineDash([6,6]);ctx.beginPath();ctx.arc(0,0,R*.6,0,TAU);ctx.stroke();ctx.setLineDash([]);ctx.restore();
