// ---------- HUD ----------
const hudEls={hud0:document.getElementById('hud')};['hpT','hpB','enT','enB','enBar','misT','sigT','sigB','sigBar','bossBar','bossB','score','dashC','pulseC','lvC','xpB','tDash','tPulse','bcBox','bcB','bcBar','biT','biB','biBar','jamBar','jamB','cargoC','wSec','wLom','wSub','eTime','eB','eStep','eRec','chgC','comboC','tCharge','aimC'].forEach(id=>hudEls[id]=document.getElementById(id));
const hudCache={};
function setT(id,v){if(touchMode)v=kh(v);if(hudCache[id]!==v){hudCache[id]=v;hudEls[id].textContent=v;}}
function setS(id,v){const k=id+'s';if(hudCache[k]!==v){hudCache[k]=v;hudEls[id].style.transform=`scaleX(${v})`;}}
function setC(id,c,on){const k=id+c;if(hudCache[k]!==on){hudCache[k]=on;hudEls[id].classList.toggle(c,on);}}
function setF(id,f){const k=id+'f',v=Math.round(clamp(f,0,1)*50)*2;if(hudCache[k]!==v){hudCache[k]=v;hudEls[id].style.setProperty('--f',v+'%');}}
function mName(M){return M?String(M.name).replace(/^Комната босса · /,''):'';}
function hudClean(v){return String(v==null?'':v).replace(/\s·\sФАЗА\s\d+/g,'').replace(/ФАЗА\s\d+\s·\s/g,'').replace(/(\d+)[,.](\d)\s?[сС](?![А-ЯЁа-яё])/g,(m,a,b)=>Math.ceil(+(a+'.'+b))+' С');}
function setH(id,h){const k=id+'h';if(hudCache[k]!==h){hudCache[k]=h;hudEls[id].hidden=h;}}
function updateHUD(){
  const p=G.player,st=G.st;if(!p)return;
  setT('hpT',Math.ceil(p.hp)+'/'+st.maxHp+(G.wear>0?' · ИЗНОС':''));setS('hpB',(p.hp/st.maxHp).toFixed(3));
  setS('enB',(p.en/100).toFixed(3));setC('enBar','full',p.en>=100);
  setT('misT',mName(MISSIONS[G.m-1]).toUpperCase());
  const bc=G.bc;
  setH('bcBox',!bc);
  if(G.lockGun>0||G.lockShield>0||G.lockDash>0)hintOnce('lockhud',(G.lockShield>0?'ЩИТ ':'')+(G.lockDash>0?'РЫВОК ':'')+(G.lockGun>0?'ОРУДИЕ ':'')+'НА ХРАНЕНИИ','#8fd8ff');
  if(bc){
    setH('sigBar',true);setH('bossBar',true);
    let s;if(bc.done)s=MISSIONS[G.m-1].transmit?'СИГНАЛ ПЕРЕДАН':'МАЯК ЗАРЯЖЕН';
    else if(bc.cool>0)s='ПРОДУВКА';
    else if(bc.transStarted&&!bc.transDone)s=(bc.charge>=80?'ПЕРЕДАЧА · ':'ПЕРЕДАЧА НА ПАУЗЕ · ')+Math.ceil(bc.trans)+' С';
    else if(bc.transDone)s='ПЕРЕДАЧА ЗАВЕРШЕНА';
    else s='ЗАРЯД'+(bc.drain>0?' ▼':bc.inRing?' ▲':'');
    setT('sigT',s);setS('bcB',(bc.charge/100).toFixed(3));setC('bcBar','cool',bc.cool>0);
    setT('biT',bc.barrier>0?'ЩИТ':'');setS('biB',(bc.hp/bc.maxHp).toFixed(3));setC('biBar','hit',bc.hitF>0);
    const j=G.jam&&G.jam.st!=='enter'?G.jam:null;setH('jamBar',!j);if(j)setS('jamB',(j.hp/j.maxHp).toFixed(4));
    setH('cargoC',false);setT('cargoC','ГРУЗ '+p.cargo+'/'+st.cargo);setC('cargoC','ok',p.cargo>0);
  }else{
    setH('cargoC',true);
    const SB=G.sb&&G.sb.st!=='enter'?G.sb:null,boss=!!SB||(G.boss&&G.boss.st!=='enter');
    setH('bossBar',!boss);setH('sigBar',!!boss);
    if(SB){setT('sigT',hudClean(sbHud(SB)));setS('bossB',(SB.hp/SB.maxHp).toFixed(4));}
    else if(boss){setT('sigT',G.boss.over>0?'ПЕРЕГРУЗКА':'СТРАЖ');setS('bossB',(G.boss.hp/G.boss.maxHp).toFixed(4));}
    else{const pr=G.bossSpawned?1:sigProgress()*((MISSIONS[G.m-1].boss||MISSIONS[G.m-1].sboss)?0.85:1);setT('sigT','СИГНАЛ');setS('sigB',pr.toFixed(3));}
  }
  hudEls.score.firstChild.nodeValue=fmt(G.score);
  const blocked=dashBlocked();const dr=p.dashCd<=0&&!blocked;
  setT('dashC',blocked?'РЫВОК · ПОМЕХИ':'РЫВОК');setF('dashC',p.dashCd>0?1-p.dashCd/(p.dashCdMax||st.dashCd||1):0);setC('dashC','ok',dr);setC('dashC','bad',blocked);setC('tDash','cd',!dr);
  const pr=p.en>=100;setT('pulseC',pr?'ИМПУЛЬС [E]':'ИМПУЛЬС');setF('pulseC',pr?0:p.en/100);setC('pulseC','ok',pr);setC('tPulse','cd',!pr);
  setT('lvC','ЩИТ');setH('lvC',!st.shieldCd);setC('lvC','ok',!!(st.shieldCd&&p.shieldUp));setS('xpB',(G.xp/G.need).toFixed(3));
  chargeChip();
}

// ---------- Экраны ----------
const SCREENS=['sMenu','sCodex','sIntro','sLevel','sDone','sPause','sOver','sMap','sShop','sSave','sDev','sHangar','sCycle','sReport','sSet','sArsenal'];
const TAPGUARD={sLevel:350,sDone:500,sOver:500};
function show(id){if(G.scrId!==id){G.scrId=id;G.scrAt=performance.now();}if(G.state!=='menu')histArm();if(id&&isMob()){$('#banner').classList.remove('show');}SCREENS.forEach(s=>$('#'+s).hidden=s!==id);if(G.state!=='play'&&G.state!=='world'&&typeof radioClear==='function')radioClear();$('#hud').hidden=!['play','levelup','pause','world'].includes(G.state)||isMob()&&(G.state==='levelup'||G.state==='pause');
  $('#hud').classList.toggle('world',!!G.world);$('#hud').classList.toggle('endless',G.mode==='endless');
  $('#scoreL').textContent=G.mode==='endless'?'УНИЧТОЖЕНО':'ОЧКИ';
  $('#devBar').hidden=!(G.devRun&&['play','levelup','pause','intro'].includes(G.state));$('#devBtn').hidden=!(G.devRun&&G.state==='play');
  if(G.state!=='play')$('#devPanel').hidden=true;
  $('#touch').hidden=!(touchMode&&(G.state==='play'||G.state==='world'));
  if(G.state!=='world'){$('#wcard').hidden=true;G.cardKey=null;}updateCursor();/*DEVW*/if(window.DEVW)DEVW.ui();
  if(G.state!=='world')joyUnlock();if(!$('#touch').hidden&&isMob())layoutTouch();ctxBtnSync();}
document.addEventListener('click',e=>{if(!touchMode)return;const sc=G.scrId,g=TAPGUARD[sc];if(!g||performance.now()-G.scrAt>=g)return;const el=e.target.closest&&e.target.closest('section');if(el&&el.id===sc){e.stopPropagation();e.preventDefault();}},true);
function renderSettings(){
  document.querySelectorAll('[data-settings]').forEach(box=>{
    if(box.closest('#sMenu,#sPause')){if(box.innerHTML)box.innerHTML='';return;}
    box.innerHTML=`
      <button class="tog ${SET.amb?'on':''}" data-k="amb"><span>МУЗЫКА${MUS.lastName&&SET.amb?' · «'+MUS.lastName+'»':''}</span><span>${SET.amb?'ВКЛ':'ВЫКЛ'}</span></button>
      <label class="vol"><span>ГРОМКОСТЬ МУЗЫКИ</span><input type="range" min="0" max="1" step="0.05" value="${SET.ambVol}" data-vol id="vol-${box.closest('section').id}"></label>
      <button class="tog ${SET.sfx?'on':''}" data-k="sfx"><span>ЗВУК</span><span>${SET.sfx?'ВКЛ':'ВЫКЛ'}</span></button>
      <button class="tog ${SET.fx?'on':''}" data-k="fx"><span>ЭФФЕКТЫ · частицы и тряска</span><span>${SET.fx?'ВКЛ':'ВЫКЛ'}</span></button>
      <button class="tog ${SET.manual?'on':''}" data-k="manual"><span>${touchMode?'ПРИЦЕЛ · НА ТЕЛЕФОНЕ ВСЕГДА АВТО':'ПРИЦЕЛ МЫШЬЮ · T'}</span><span>${SET.manual?'РУЧНОЙ':'АВТО'}</span></button>
      <button class="tog ${SET.radio?'on':''}" data-k="radio"><span>ПЕРЕХВАТЫ · радиоэфир</span><span>${SET.radio?'ВКЛ':'ВЫКЛ'}</span></button>${FS.rowPC()}`+(box.closest('#sMenu')?resetBlock():'');
  });
  renderSetScreen();
}
// ---- экран настроек (0.6.0) ----
const SEGS={fsMode:[['ПОЛНЫЙ ЭКРАН',[['off','ВЫКЛ'],['auto','ПРИ ПОЛЁТЕ'],['always','ВСЕГДА']]]],orient:[['ОРИЕНТАЦИЯ',[['auto','АВТО'],['land','АЛЬБОМ'],['port','КНИЖНАЯ']]]],zoom:[['МАСШТАБ',[[.85,'КРУПНЕЕ'],[1,'СТАНДАРТ'],[1.15,'ДАЛЬШЕ']]]],textScale:[['ТЕКСТ',[[1,'ОБЫЧНЫЙ'],[1.15,'КРУПНЫЙ'],[1.3,'ОЧЕНЬ КРУПНЫЙ']]]],
  quality:[['КАЧЕСТВО',[['auto','АВТО'],[0,'ЭКОНОМ'],[1,'СТАНДАРТ'],[2,'ВЫСОКОЕ']]]],fps:[['КАДРЫ',[[60,'60'],[30,'30']]]],shake:[['ТРЯСКА',[[0,'НЕТ'],[.5,'СЛАБАЯ'],[1,'ПОЛНАЯ']]]],
  btnSize:[['РАЗМЕР КНОПОК',[[.85,'МЕНЬШЕ'],[1,'СТАНДАРТ'],[1.2,'КРУПНЕЕ']]]],btnAlpha:[['ПРОЗРАЧНОСТЬ КНОПОК',[[.45,'СИЛЬНАЯ'],[.7,'СРЕДНЯЯ'],[1,'НЕТ']]]],
  hand:[['РУКА',[['r','ПРАВАЯ'],['l','ЛЕВАЯ']]]],stick:[['СТИК',[['float','ПЛАВАЮЩИЙ'],['fixed','ЗАКРЕПЛЁННЫЙ']]]]};
function segHTML(k){const [lab,opts]=SEGS[k][0];return `<div class="setrow"><div class="eyebrow">${lab}</div><div class="seg" data-seg="${k}">${opts.map(([v,n])=>`<button data-v="${v}" class="${String(SET[k])===String(v)?'on':''}">${n}</button>`).join('')}</div></div>`;}
function togHTML(k,lab,on,off){return `<button class="tog ${SET[k]?'on':''}" data-k="${k}"><span>${lab}</span><span>${SET[k]?(on||'ВКЛ'):(off||'ВЫКЛ')}</span></button>`;}
function renderSetScreen(){const B=$('#setBody');if(!B||G.state!=='settings')return;const ios=/iP(hone|ad|od)/.test(navigator.userAgent)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1,tch=touchMode||isMob();
  const fxl=!SET.fx?'off':SET.lessFx?'less':'full',fxSeg=`<div class="setrow"><div class="eyebrow">ЭФФЕКТЫ</div><div class="seg">${[['full','ПОЛНЫЕ'],['less','МЕНЬШЕ'],['off','ВЫКЛ']].map(([v,n])=>`<button data-fxl="${v}" class="${fxl===v?'on':''}">${n}</button>`).join('')}</div></div>`;
  B.innerHTML=`<div class="setgrp"><div class="cx-h2">ЗВУК</div>${togHTML('amb','МУЗЫКА')}
      <label class="vol"><span>ГРОМКОСТЬ МУЗЫКИ</span><input type="range" min="0" max="1" step="0.05" value="${SET.ambVol}" data-vol id="vol-sSet"></label>${togHTML('sfx','ЗВУКИ')}
      ${ios?'<p class="note">Нет звука? Проверьте беззвучный режим.</p>':''}</div>
    <div class="setgrp"><div class="cx-h2">УПРАВЛЕНИЕ</div>${tch?`${segHTML('btnSize')}${segHTML('btnAlpha')}${segHTML('hand')}${segHTML('stick')}
      ${togHTML('dashSwipe','РЫВОК СВАЙПОМ')}${togHTML('oneHand','ОДНОЙ РУКОЙ')}${navigator.vibrate?togHTML('haptics','ВИБРАЦИЯ'):''}`:togHTML('manual','ПРИЦЕЛ МЫШЬЮ')}</div>
    <div class="setgrp"><div class="cx-h2">ЭКРАН</div>${segHTML('fsMode')}${FS.can()?'':`<p class="note" id="fsNote">${FS.noteText()}</p>`}${FS.hintKind()&&!FS.can()?'<div><button class="wbtn" data-fshint>КАК УБРАТЬ ПАНЕЛИ</button></div>':''}${FS.orientOK()?segHTML('orient'):''}
      ${segHTML('zoom')}${G.ff==='desk'?segHTML('uiSize'):''}${segHTML('textScale')}${segHTML('quality')}${segHTML('fps')}${segHTML('shake')}${fxSeg}${devUnlocked()?'<p class="fsdiag">'+FS.diag()+'</p>':''}</div>
    <div class="setgrp"><div class="cx-h2">ПРОЧЕЕ</div>${togHTML('radio','РАДИОЭФИР')}${togHTML('softInv','БЕЗ ПЕРЕВОРОТА УПРАВЛЕНИЯ')}${togHTML('noErase','БЕЗ СТИРАНИЯ ИНТЕРФЕЙСА')}${G.setFrom==='menu'?resetBlock():''}</div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-fxl]');if(!b)return;const v=b.dataset.fxl;SET.fx=v!=='off';SET.lessFx=v==='less';saveSet();applySettings();renderSettings();buzz('tap');});
function applySettings(){document.documentElement.style.setProperty('--fs',SET.textScale||1);ffUpdate();resize();layoutTouch();}
function openSettings(from){G.setFrom=from;G.setPrev=G.state;G.state='settings';renderSetScreen();show('sSet');}
function closeSettings(){if(G.state!=='settings')return;if(G.setFrom==='pause'){G.state='pause';renderSettings();show('sPause');}else{toMenu();}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-seg] [data-v]');if(!b)return;const k=b.closest('[data-seg]').dataset.seg,raw=b.dataset.v,opts=SET_OPT[k];if(!opts)return;
  const v=opts.find(o=>String(o)===raw);if(v===undefined)return;SET[k]=v;saveSet();applySettings();renderSetScreen();buzz('tap');});
// ===== 0.6.2: полный экран — один модуль =====
const FS={caps:null,state:'off',lastErr:'',wanted:false,tried:false,src:'',chgAt:0,_t:0,
  probe(){const d=document,el=d.documentElement,ua=navigator.userAgent||'';const ipad=/iPad/.test(ua)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1),iphone=/iPhone|iPod/.test(ua)&&!ipad;
    let iframe=false;try{iframe=window.self!==window.top;}catch(e){iframe=true;}
    const webview=/Telegram|FBAN|FBAV|Instagram|VKClient|WhatsApp|Line\/|; wv\)/i.test(ua);let standalone=false;try{standalone=(window.matchMedia&&matchMedia('(display-mode: standalone)').matches)||navigator.standalone===true;}catch(e){}
    const api=!!(el.requestFullscreen||el.webkitRequestFullscreen),policy=!!(d.fullscreenEnabled||d.webkitFullscreenEnabled);
    this.caps={api,prefixed:!el.requestFullscreen&&!!el.webkitRequestFullscreen,iframe,policy,iphone,ipad,ios:iphone||ipad,android:/Android/i.test(ua),webview,standalone,mac:/Mac/.test(navigator.platform||'')&&!ipad};
    if(api&&!policy&&!iphone&&!standalone){this.lastErr='policy';this.state='denied';this.immersive(true);}
    if(!iframe||standalone)this.immersive(true);return this.caps;},
  c(){return this.caps||this.probe();},
  can(){const c=this.c();return c.api&&c.policy&&!c.iphone&&!c.standalone&&this.lastErr!=='policy';},
  is(){return !!(document.fullscreenElement||document.webkitFullscreenElement);},
  enter(src){const c=this.c();if(this.is())return true;if(!this.can()){this.state='denied';this.sync();return false;}
    let act=true;try{if(navigator.userActivation&&!navigator.userActivation.isActive)act=false;}catch(e){}
    if(!act){this.lastErr='gesture';this.sync();return false;}
    const el=document.documentElement;this.state='pending';this.wanted=true;this.tried=true;this.src=src||'';if(this.lastErr==='gesture')this.lastErr='';
    let p=null;try{p=el.requestFullscreen?el.requestFullscreen({navigationUI:'hide'}):el.webkitRequestFullscreen();}catch(err){this.fail(err);return false;}
    this.curtain(true);clearTimeout(this._t);this._t=setTimeout(()=>{if(this.state==='pending')this.fail({name:'Timeout'});},1500);
    if(p&&p.then)p.then(()=>{},err=>this.fail(err));return true;},
  fail(err){clearTimeout(this._t);if(this.is()){this.onChange();return;}const n=(err&&err.name)||'';this.lastErr=(n==='TypeError'||n==='NotAllowedError'||n==='Timeout'||n==='SecurityError')?'policy':'other';
    this.state='denied';this.wanted=false;this.curtain(false);this.immersive(true);
    if(this.src==='auto'&&isMob()){if(!SET.fsHintShown){SET.fsHintShown=true;saveSet();toast('ПОЛНЫЙ ЭКРАН НЕДОСТУПЕН','Игра расширится на всё доступное место. Как убрать панели браузера — кнопка ⛶ в меню.');}}
    else if(this.src&&this.src!=='always')this.card(true);this.sync();},
  exit(){this.wanted=false;try{const p=document.exitFullscreen?document.exitFullscreen():document.webkitExitFullscreen&&document.webkitExitFullscreen();if(p&&p.catch)p.catch(()=>{});}catch(err){}},
  toggle(src){if(this.is())this.exit();else if(this.can())this.enter(src);else this.card(true);},
  immersive(on){document.documentElement.classList.toggle('fs-imm',!!on);},
  curtain(on){const el=$('#fsCurtain');if(!el)return;if(!SET.fx){el.classList.remove('show');return;}el.classList.toggle('show',!!on);},
  onChange(){clearTimeout(this._t);const on=this.is();this.chgAt=performance.now();this.state=on?'native':'off';
    if(on){this.lastErr='';this.immersive(true);if((G.state==='play'||G.state==='world')&&this.src==='key')G.resumeK=Math.max(G.resumeK||0,.5);
      if(this.c().android&&SET.orient!=='auto'&&screen.orientation&&screen.orientation.lock){try{screen.orientation.lock(SET.orient==='land'?'landscape':'portrait').catch(()=>{});}catch(e){}}}
    else{if(screen.orientation&&screen.orientation.unlock){try{screen.orientation.unlock();}catch(e){}}if(G.state==='play'||G.state==='world')pause();}
    requestAnimationFrame(()=>requestAnimationFrame(()=>{try{resize();if(typeof readSafe==='function')readSafe();if(typeof layoutTouch==='function')layoutTouch();}catch(e){}this.curtain(false);this.sync();}));
    this.sync();},
  orientOK(){const c=this.c();return !!(c.android&&screen.orientation&&screen.orientation.lock&&this.can());},
  hintKind(){const c=this.c();if(c.standalone)return null;if(c.webview)return 'open-browser';if(c.iphone)return c.iframe?'safari-toolbar':'home-screen';if(!isMob())return 'f11';if(c.ipad)return 'safari-toolbar';return 'direct-link';},
  hintText(){const k=this.hintKind(),mac=this.c().mac;switch(k){
    case 'f11':return `Сайт не пускает игру во весь экран сам. Нажмите <b>${mac?'⌃⌘F':'F11'}</b>: браузер скроет вкладки и адресную строку. Выход — то же сочетание.`;
    case 'safari-toolbar':return 'На iPhone и iPad Safari не разрешает играм открываться во весь экран. Сделайте это вручную: нажмите значок меню страницы слева в адресной строке → <b>«Скрыть панель инструментов»</b>, и поверните телефон горизонтально. Вернуть панель — касание верхнего края.';
    case 'open-browser':return 'Внутри приложения игра не может занять весь экран. Откройте её в Safari или Chrome: меню <b>«…»</b> → <b>«Открыть в браузере»</b>. Прогресс перенесите кодом сохранения.';
    case 'home-screen':return 'Чтобы игра открывалась без адресной строки: <b>«Поделиться»</b> → <b>«На экран Домой»</b>. Запускайте её с иконки — как приложение.';
    case 'direct-link':return 'Сайт не разрешает игре открываться во весь экран. Откройте ссылку на игру напрямую в Chrome (меню <b>⋮</b> → <b>«Открыть в Chrome»</b>) или добавьте её на главный экран.';
    default:return 'Игра уже занимает весь экран.';}},
  noteText(){const c=this.c();if(c.standalone)return 'Игра запущена как приложение — панелей браузера нет.';if(this.can())return 'Доступно: настоящий полный экран'+(this.is()?' · сейчас включён':'')+'.';return 'Этот браузер не пускает игру во весь экран — игра расширится на всё доступное место.';},
  diag(){const c=this.c();return `СРЕДА ${c.iframe?'вложена':'своя'} · API ${c.api?'да':'нет'} · РАЗРЕШЕНИЕ ${c.policy?'да':'нет'} · ${c.iphone?'iPhone':c.ipad?'iPad':c.android?'Android':'ПК'}${c.webview?' · WebView':''}${c.standalone?' · standalone':''} · попытка: ${this.lastErr?'отказ ('+this.lastErr+')':this.state==='native'?'успех':this.tried?'успех':'не было'}`;},
  rowPC(){if(isMob())return '';const L={off:'ВЫКЛ',auto:'ПРИ ПОЛЁТЕ',always:'ВСЕГДА'};return `<button class="tog ${SET.fsMode!=='off'?'on':''}" data-fscycle><span>ПОЛНЫЙ ЭКРАН · ${this.is()?'СЕЙЧАС ВКЛ':this.can()?'F11':'НЕДОСТУПЕН'}</span><span>${L[SET.fsMode]||'ВЫКЛ'}</span></button><p class="fsdiag">${this.diag()}</p>`;},
  card(on){const el=$('#fsCard');if(!el)return;if(on){$('#fsCardText').innerHTML=this.hintText();el.hidden=false;const b=$('#bFsCardOk');if(b&&!touchMode)b.focus();}else el.hidden=true;},
  sync(){const c=this.c(),on=this.is(),can=this.can();
    const b=$('#bFs');if(b){b.hidden=!(isMob()&&!c.standalone);b.classList.toggle('on',on);b.classList.toggle('q',!on&&!can);b.textContent=on?'✕':'⛶';b.setAttribute('aria-pressed',on?'true':'false');b.title=on?'Оконный режим':can?'Во весь экран':'Как убрать панели браузера';}
    const pc=$('#bFsPc');if(pc){pc.hidden=isMob()||c.standalone;pc.innerHTML=on?'ОКОННЫЙ РЕЖИМ <kbd>F11</kbd>':'ПОЛНЫЙ ЭКРАН <kbd>F11</kbd>';pc.setAttribute('aria-pressed',on?'true':'false');}
    const fr=$('#bFsResume'),pf=$('#bPauseFs'),rs=$('#bResume');if(fr&&pf&&rs){fr.hidden=!(this.wanted&&can&&!on);pf.hidden=!(can&&!on&&!this.wanted);rs.classList.toggle('primary',fr.hidden);}
    if(G.state==='settings'&&typeof renderSetScreen==='function')renderSetScreen();
    if(!isMob()&&(G.state==='menu'||G.state==='pause')){document.querySelectorAll('[data-fscycle]').forEach(el=>{el.outerHTML=this.rowPC().replace(/<p class="fsdiag">.*<\/p>$/,'');});document.querySelectorAll('.fsdiag').forEach(el=>{el.textContent=this.diag();});}}
};
function fsCan(){return FS.can();}function fsIs(){return FS.is();}function fsEnter(){return FS.enter('btn');}function fsExit(){FS.exit();}function fsSync(){FS.sync();}
document.addEventListener('click',e=>{if(e.target.closest('#bFs,#bFsPc')){FS.toggle('btn');buzz('tap');return;}
  if(e.target.closest('#bFsResume')){FS.enter('resume');resume();return;}
  if(e.target.closest('#bPauseFs')){FS.enter('pause');return;}
  if(e.target.closest('[data-fshint]')){FS.card(true);return;}
  if(e.target.closest('#bFsCardOk')){FS.card(false);return;}
  const cy=e.target.closest('[data-fscycle]');if(cy){const o=SET_OPT.fsMode;SET.fsMode=o[(o.indexOf(SET.fsMode)+1)%o.length];saveSet();renderSettings();FS.sync();return;}});
// режим «при полёте»: вход по кнопкам старта и по «продолжить», если игрок хотел полный экран (жест ещё активен)
document.addEventListener('click',e=>{const b=e.target.closest('#bWorld,#bEndless,#bWorldNew,#bResume');if(!b||SET.fsMode==='off'||FS.is())return;if(b.id==='bResume'&&!FS.wanted)return;
  if(!FS.can()){if(isMob()&&b.id!=='bResume'&&!SET.fsHintShown){SET.fsHintShown=true;saveSet();toast('БОЛЬШЕ МЕСТА','Скройте панели браузера — кнопка ⛶ в меню подскажет, как.');}return;}FS.enter('auto');},true);
// режим «всегда»: первое касание в меню или на паузе
document.addEventListener('pointerup',e=>{if(SET.fsMode!=='always'||FS.is()||!FS.can())return;if(G.state==='play'||G.state==='world'||G.state==='settings')return;if(e.pointerType==='mouse'&&e.button!==0)return;if(e.target.closest('#bFs,#bFsPc,#fsCard,[data-fscycle],[data-seg]'))return;FS.enter('always');},true);
document.addEventListener('fullscreenchange',()=>FS.onChange());
document.addEventListener('webkitfullscreenchange',()=>FS.onChange());
document.addEventListener('click',e=>{const b=e.target.closest('.tog[data-k]');if(!b)return;const k=b.dataset.k;SET[k]=!SET[k];saveSet();audioInit();applyAudio();renderSettings();updateCursor();});
document.addEventListener('input',e=>{if(e.target.matches('[data-vol]')){SET.ambVol=+e.target.value;saveSet();applyAudio();}});
function doneCountS(S){const k=G.save;G.save=S;const n=doneCount();G.save=k;return n;}
function renderMenu(){try{$('#wvNote').hidden=!/Telegram|FBAN|FBAV|Instagram|VKClient|WhatsApp|Line\/|; wv\)/i.test(navigator.userAgent);}catch(e){}
  renderRecord();const S=G.save&&validSave(G.save)?G.save:null;
  $('#bWorld').firstChild.nodeValue=S?'ПРОДОЛЖИТЬ ':'НАЧАТЬ ';
  $('#bWorldNew').hidden=!S;$('#bWorldNew').textContent='НОВЫЙ ПОЛЁТ';newConfirm=0;
  const eb=bestEndless();$('#bEndBest').textContent=eb?mmss(eb.t):'';$('#bDev').hidden=!devUnlocked();/*DEVW*/if(window.DEVW)DEVW.menu();
}
