    const B=G.sb&&G.sb.alive?G.sb:G.boss&&G.boss.alive?G.boss:G.jam&&G.jam.alive?G.jam:null;if(B)edgeArrow(B.x,B.y,'#ff6b8a',14,'БОСС');
