    if(d===0&&reach>50){const si=sectorIdx(x,y),b=WORLD.sectors[si].box,own=Math.min(x-b[0],b[2]-x,y-b[1],b[3]-y);if(own<reach+200)d=riftInfo(x,y).d;else d=-own;}
