function mapSpanMin(){return isMob()?2200:3500;}
function mapViewInit(){const p=G.player,sp=mapSpanDef();G.mapView={cx:p.x,cy:p.y,span:sp*1.25,tspan:sp,vx:0,vy:0};G.mapOpenT=performance.now();G.mapTipPin=null;}
