function invSpawnCell(b,c){const q=invCellPos(b,c.i);c.e=spawnEnemy('invcell',q.x,q.y,{noAffix:true,noLoot:true,spawnT:.8,cell:c});c.e.hp=c.e.maxHp=Math.round(160*sbRank());c.label=null;c.locked=false;c.open=0;}
