function witHurt100(w,d){w.hp-=d;w.flash=.08;if(w.hp<=0&&w.alive){kill(w);}else if(!w.hurtHint){w.hurtHint=1;floater(w.x,w.y-24,'СВИДЕТЕЛЬ ПОД ОГНЁМ','#ffffff');}}
