    for(let y=20;y<top;y+=36){ctx.beginPath();ctx.moveTo(P_-12,y);ctx.lineTo(P_+12,y+12);ctx.stroke();}for(let y=bot+20;y<len;y+=36){ctx.beginPath();ctx.moveTo(P_-12,y);ctx.lineTo(P_+12,y+12);ctx.stroke();}
