  if(!e.lp95){e.lp95=1;e.skin95=lostSkin95();e.nm95=LOSTN95[Math.random()*LOSTN95.length|0]+' · '+String(100+Math.random()*899|0);e.dcd95=1.5;e.pcd95=5;e.ccd95=4;e.fcd95=1;e.elite95=1;e.face=Math.atan2(pdy,pdx);}
