  const warn=B.warn&&B.turn<=0&&B.ph<3;ctx.strokeStyle=warn&&Math.sin(t*12)>0?C110.white:C110.zero;ctx.lineWidth=2;ctx.beginPath();bandPath49(X);ctx.stroke();
