function postRect(r){const a=postXY(r[0],r[1]),b=postXY(r[2],r[3]);return {x0:Math.min(a[0],b[0]),y0:Math.min(a[1],b[1]),x1:Math.max(a[0],b[0]),y1:Math.max(a[1],b[1])};}
