  P.trig=A.trig?(()=>{const [x,y]=postXY(...A.trig);return {x,y,hit:false};})():null;P.figs=[];P.strobe=null;P.figT=rnd(7,12);P.strT=rnd(14,22);P.mbT=0;P.mbI=0;P.rift=0;
