function ramStop(){/* рывок (кадры замаха→рывка включительно) + занос 0,7 с при v*=.92 за кадр */return RAM_V*(RAM_T+2/60+.92*(1-Math.pow(.92,42))/.08/60)*(G.eSpd||1);}
