    for(let i=-3;i<=3;i++){const on=((Math.floor(t*6)+i*3)%5)===0;ctx.fillStyle=on?'#ffffff':'rgba(159,216,255,.35)';ctx.fillRect(i*4-.6,-6,1.2,3);ctx.fillRect(i*4-.6,3,1.2,3);}
