  [...B.querySelectorAll('.setgrp')].forEach(g=>{[...g.children].forEach(ch=>{if(ch.classList.contains('cx-h2')||used.has(ch))return;if(ch.querySelector&&[...used].some(u=>ch.contains(u)))return;put('game',ch,'',{note:''});});});
