addEventListener('unhandledrejection',e=>{DVX.errs.push({t:Date.now(),m:'promise: '+String(e.reason&&e.reason.message||e.reason).slice(0,200),s:'',seen:0});if(DVX.errs.length>40)DVX.errs.shift();});

