  if(k==='stun'){c66Ring(p.x,p.y-80,220,'#ffd24d',.8,3);c66Sting('impact');if(c66Mode()==='full'){hs90(.12,2);trauma90(.45);slow95(.6,.35);}c66Cap('ОГЛУШЁН · УРОН ×2',p.x,p.y-80,'#ffd24d',1.8);}
  if(k==='silence'){c66Duck(.05,1.7);c66Sting('rumble');}
