  1:{pos:[.86,.2],halo:26,rays:80,core:2.2,pts:[[-.05,.32],[.17,.12],[.42,-.05]],arcA:.85,arcTh:1,dens:.75,peak:.2,white:0,violet:1,glow:.8,lanes:.7,voids:1,stretch:[1,1],mid:0,mines:0,dim:0},
